// HAND-OWNED (quick-log). Not generated by Bubblewrap.
package io.github.palo007.twa.quicklog

import android.app.Activity
import android.content.Context
import android.util.Log
import android.widget.Toast
import com.google.androidbrowserhelper.trusted.TwaProviderPicker

/**
 * TWA-03: when no TWA provider (Chrome) is available, androidbrowserhelper falls back to a Custom Tab in
 * another browser (e.g. Brave) that has its own storage, so Questa looks empty. Tell the user once.
 * The flag is cleared when the TWA path is back, so the notice re-arms if Chrome goes away again.
 */
object ProviderNotice {
    enum class Decision { SHOW, RESET, NONE }

    private const val TAG = "QuestaLauncher"
    private const val PREFS = "questa_launcher"
    private const val KEY_SHOWN = "no_twa_notice_shown"
    const val MESSAGE = "Chrome is off or missing. Questa opens in another browser with separate storage, " +
        "so your data is not there. Turn Chrome back on."

    @JvmStatic
    fun decide(launchMode: Int, alreadyShown: Boolean): Decision =
        if (launchMode == TwaProviderPicker.LaunchMode.TRUSTED_WEB_ACTIVITY) {
            if (alreadyShown) Decision.RESET else Decision.NONE
        } else {
            if (alreadyShown) Decision.NONE else Decision.SHOW
        }

    /** Never blocks or delays the launch; callers still wrap it in try/catch. */
    @JvmStatic
    fun maybeShow(activity: Activity) {
        val app = activity.applicationContext
        val mode = TwaProviderPicker.pickProvider(activity.packageManager).launchMode
        val p = app.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        when (decide(mode, p.getBoolean(KEY_SHOWN, false))) {
            Decision.SHOW -> {
                Log.i(TAG, "no TWA provider (mode=$mode), showing notice")
                Toast.makeText(app, MESSAGE, Toast.LENGTH_LONG).show()
                p.edit().putBoolean(KEY_SHOWN, true).apply()
            }
            Decision.RESET -> p.edit().putBoolean(KEY_SHOWN, false).apply()
            Decision.NONE -> Unit
        }
    }
}
